-- Empty prospective, explicitly configured elapsed-UTC clocks. No backfill/default/grant/scheduler.
create function valid_approval_due_definition(d jsonb)returns boolean language plpgsql immutable as $$
declare x jsonb;k text;s text;expanded text;
begin
 if jsonb_typeof(d)is distinct from'object'or(select count(*)from jsonb_object_keys(d))<>8 or not(d?&array['workerIds','sourceKinds','clockBasis','cohort','dueAfterMinutes','target','locale','template'])or d->>'clockBasis'is distinct from'StagePendingUTC'or d->>'cohort'is distinct from'NewInstances'or jsonb_typeof(d->'dueAfterMinutes')is distinct from'number'or(d->>'dueAfterMinutes')!~'^[0-9]+$'or(d->>'dueAfterMinutes')::numeric not between 1 and 527040 or jsonb_typeof(d->'workerIds')is distinct from'array'or jsonb_array_length(d->'workerIds')>200 or jsonb_typeof(d->'sourceKinds')is distinct from'array'or jsonb_array_length(d->'sourceKinds')not between 1 and 3 or jsonb_typeof(d->'locale')is distinct from'string'or work_period_notice_units(d->>'locale')>100 or(d->>'locale')!~'^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$'then return false;end if;
 if(select count(distinct v)from jsonb_array_elements_text(d->'workerIds')v)<>jsonb_array_length(d->'workerIds')or(select count(distinct v)from jsonb_array_elements_text(d->'sourceKinds')v)<>jsonb_array_length(d->'sourceKinds')then return false;end if;
 for x in select value from jsonb_array_elements(d->'workerIds')loop if jsonb_typeof(x)is distinct from'string'or work_period_notice_units(x#>>'{}')not between 1 and 200 or btrim(x#>>'{}')<>x#>>'{}'then return false;end if;end loop;
 for x in select value from jsonb_array_elements(d->'sourceKinds')loop if jsonb_typeof(x)is distinct from'string'or x#>>'{}'not in('Work','Material','Creation')then return false;end if;end loop;
 x=d->'target';if jsonb_typeof(x)is distinct from'object'or(select count(*)from jsonb_object_keys(x))<>2 or not(x?&array['userId','role'])or jsonb_typeof(x->'userId')is distinct from'string'or(x->>'userId')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'or jsonb_typeof(x->'role')is distinct from'string'or work_period_notice_units(x->>'role')not between 1 and 100 or btrim(x->>'role')<>x->>'role'then return false;end if;
 x=d->'template';if jsonb_typeof(x)is distinct from'object'or(select count(*)from jsonb_object_keys(x))<>3 or not(x?&array['key','subject','body'])or x->>'key'is distinct from'approval.overdue_or_escalated'then return false;end if;
 foreach k in array array['subject','body']loop s=x->>k;if jsonb_typeof(x->k)is distinct from'string'or work_period_notice_units(s)not between 1 and(case when k='subject'then 200 else 8000 end)or btrim(s)<>s then return false;end if;expanded=s;expanded=regexp_replace(expanded,'\{\{\s*workerCode\s*\}\}',repeat('x',200),'g');expanded=regexp_replace(expanded,'\{\{\s*sourceRef\s*\}\}',repeat('x',239),'g');expanded=regexp_replace(expanded,'\{\{\s*stageNumber\s*\}\}','xx','g');expanded=regexp_replace(expanded,'\{\{\s*(pendingAt|dueAt)\s*\}\}',repeat('x',24),'g');if expanded~'[{}]'or work_period_notice_units(expanded)>(case when k='subject'then 1200 else 12000 end)then return false;end if;end loop;return true;
exception when others then return false;end $$;
create table approval_due_policies(id uuid primary key,organization_id text not null,legal_entity_id text not null,sequence integer not null check(sequence>0),effective_from date not null,definition jsonb not null check(valid_approval_due_definition(definition)),actor_id uuid not null references users(id),active_role text not null,reason text not null check(length(btrim(reason))between 1 and 1000),created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,legal_entity_id)references legal_entities(organization_id,id),unique(organization_id,legal_entity_id,sequence),unique(organization_id,legal_entity_id,effective_from));
create table approval_due_templates(id uuid primary key,policy_id uuid not null unique references approval_due_policies(id),event_key text not null check(event_key='approval.overdue_or_escalated'),locale text not null,subject text not null,body text not null);
create view approval_due_source_events as
 select 'Work'::text origin,i.id instance_id,i.organization_id,i.legal_entity_id,i.employee_id,null::text project_id,i.timesheet_id::text source_ref,i.source_token,i.created_at instance_created_at,e.id source_event_id,e.stage,e.transition_sequence,e.created_at activated_at,(p.definition->'stages'->e.stage->>'userId')::uuid approver_user_id,p.definition->'stages'->e.stage->>'role' approver_role
 from work_approval_events e join work_approval_instances i on i.id=e.instance_id join work_approval_policy_versions p on p.id=i.policy_id where e.event_key='approval.action_required'
 union all select case when i.operation_kind='Creation'then'Creation'else'Material'end,i.id,i.organization_id,i.legal_entity_id,i.employee_id,i.project_id,i.assignment_id,i.source_token,i.created_at,e.id,e.stage,e.transition_sequence,e.created_at,(p.definition->'stages'->e.stage->>'userId')::uuid,p.definition->'stages'->e.stage->>'role'from assignment_approval_events e join assignment_approval_instances i on i.id=e.instance_id join assignment_approval_policies p on p.id=i.policy_id where e.event_key='approval.action_required';
create table approval_due_bindings(origin text not null check(origin in('Work','Material','Creation')),instance_id uuid not null,policy_id uuid not null references approval_due_policies(id),primary key(origin,instance_id));
create table approval_due_clocks(id uuid primary key,origin text not null,instance_id uuid not null,source_event_id text not null,stage integer not null check(stage between 0 and 9),activated_at timestamptz not null,due_at timestamptz not null,approver_user_id uuid not null references users(id),approver_role text not null,foreign key(origin,instance_id)references approval_due_bindings(origin,instance_id),unique(origin,source_event_id),unique(origin,instance_id,stage));
create function approval_due_selected_policy(s approval_due_source_events)returns uuid language plpgsql stable as $$declare p approval_due_policies;begin
 select * into p from approval_due_policies where organization_id=s.organization_id and legal_entity_id=s.legal_entity_id and created_at<=s.instance_created_at and effective_from<=(s.instance_created_at at time zone'UTC')::date order by sequence desc limit 1;
 if p.id is not null and p.definition->'workerIds'?s.employee_id and p.definition->'sourceKinds'?s.origin then return p.id;end if;return null;end $$;
create function retain_approval_due_clock()returns trigger language plpgsql as $$declare s approval_due_source_events;p uuid;d integer;begin
 if new.event_key<>'approval.action_required'then return null;end if;
 select * into s from approval_due_source_events where source_event_id=new.id and origin=case when tg_table_name='work_approval_events'then'Work'else(select case when operation_kind='Creation'then'Creation'else'Material'end from assignment_approval_instances where id=new.instance_id)end;
 if s.stage=0 then p=approval_due_selected_policy(s);if p is not null then insert into approval_due_bindings values(s.origin,s.instance_id,p);end if;else select policy_id into p from approval_due_bindings where origin=s.origin and instance_id=s.instance_id;end if;
 if p is not null then select(definition->>'dueAfterMinutes')::integer into d from approval_due_policies where id=p;insert into approval_due_clocks values(gen_random_uuid(),s.origin,s.instance_id,s.source_event_id,s.stage,s.activated_at,s.activated_at+d*interval '1 minute',s.approver_user_id,s.approver_role);end if;return null;
end $$;
create trigger retained_work_due_clock after insert on work_approval_events for each row execute function retain_approval_due_clock();
create trigger retained_assignment_due_clock after insert on assignment_approval_events for each row execute function retain_approval_due_clock();
create function approval_due_current(origin_arg text,instance_arg uuid,stage_arg integer)returns boolean language plpgsql stable as $$declare n integer;terminal boolean;i work_approval_instances;a assignment_approval_instances;begin
 if origin_arg='Work'then
  select * into i from work_approval_instances where id=instance_arg;select coalesce(max(sequence),0),coalesce(bool_or(outcome->>'status'<>'Pending'),false)into n,terminal from work_approval_transitions where instance_id=instance_arg;
  return coalesce(i.id is not null and not terminal and stage_arg=n and exists(select 1 from timesheets t where t.id=i.timesheet_id and t.status='Submitted')and i.submission_id=(select id from work_submission_evidence where timesheet_id=i.timesheet_id order by sequence desc limit 1),false);
 end if;
 select * into a from assignment_approval_instances where id=instance_arg;select coalesce(max(sequence),0),coalesce(bool_or(outcome->>'status'<>'Pending'),false)into n,terminal from assignment_approval_transitions where instance_id=instance_arg;
 return coalesce(a.id is not null and origin_arg=case when a.operation_kind='Creation'then'Creation'else'Material'end and not terminal and stage_arg=n and case when a.operation_kind='Creation'then not exists(select 1 from project_allocations where id=a.assignment_id)and not exists(select 1 from assignment_versions where assignment_id=a.assignment_id)else exists(select 1 from project_allocations x where x.id=a.assignment_id and resource_assignment_revision(x)=a.source_revision)and a.source_version_id is not distinct from(select id from assignment_versions where assignment_id=a.assignment_id order by sequence desc limit 1)end,false);
end $$;
create table approval_due_runs(id uuid primary key,organization_id text not null,legal_entity_id text not null,origin text not null,instance_id uuid not null,stage integer not null,clock_id uuid references approval_due_clocks(id),sequence integer not null check(sequence>0),request_id uuid not null,request_fingerprint text not null check(request_fingerprint~'^[a-f0-9]{64}$'),actor_id uuid not null references users(id),active_role text not null,reason text not null check(length(btrim(reason))between 1 and 1000),operation_id text not null check(length(btrim(operation_id))between 1 and 200),correlation_id text not null check(length(btrim(correlation_id))between 1 and 200),source_token text not null check(source_token~'^[a-f0-9]{64}$'),source_canonical text not null,outcome jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(organization_id,legal_entity_id,request_id),unique(origin,instance_id,sequence));
create table approval_due_events(id text primary key,clock_id uuid not null unique references approval_due_clocks(id),run_id uuid not null unique references approval_due_runs(id),event_key text not null check(event_key='approval.overdue_or_escalated'),policy_class text not null check(policy_class='CONTROL_MANDATORY'),template_id uuid not null references approval_due_templates(id),operation_id text not null,correlation_id text not null,locale text not null,title text not null check(work_period_notice_units(title)between 1 and 1200),body text not null check(work_period_notice_units(body)between 1 and 12000),created_at timestamptz not null default clock_timestamp());
create table approval_due_recipients(id uuid primary key,event_id text not null references approval_due_events(id),user_id uuid not null references users(id),reasons text[] not null check(cardinality(reasons)between 1 and 2 and reasons<@array['current_stage_approver','configured_escalation_target']::text[]),in_app boolean not null check(in_app),channel_decision text not null check(channel_decision='Required'),unique(event_id,user_id));
create table approval_due_deliveries(id uuid primary key,recipient_id uuid not null unique references approval_due_recipients(id),channel text not null check(channel='InApp'),status text not null check(status='Delivered'),operation_id text not null,correlation_id text not null,attempt integer not null check(attempt=1),created_at timestamptz not null default clock_timestamp());
create table approval_due_reads(recipient_id uuid primary key references approval_due_recipients(id),user_id uuid not null references users(id),read_at timestamptz not null default clock_timestamp());
create function guard_approval_due_append()returns trigger language plpgsql as $$declare ctx jsonb;p approval_due_policies;s approval_due_source_events;c approval_due_clocks;r approval_due_runs;expected uuid;begin
 if tg_table_name='approval_due_bindings'then select * into s from approval_due_source_events where origin=new.origin and instance_id=new.instance_id and stage=0;expected=approval_due_selected_policy(s);if expected is null or new.policy_id is distinct from expected then raise exception 'Only the exact prospective new-instance cohort may bind.'using errcode='ADN02';end if;return new;end if;
 if tg_table_name='approval_due_clocks'then select * into s from approval_due_source_events where origin=new.origin and instance_id=new.instance_id and source_event_id=new.source_event_id;select pol.* into p from approval_due_policies pol join approval_due_bindings b on b.policy_id=pol.id where b.origin=new.origin and b.instance_id=new.instance_id;
  if s.instance_id is null or p.id is null or new.stage<>s.stage or new.activated_at is distinct from s.activated_at or new.activated_at<statement_timestamp()or new.activated_at>clock_timestamp()or new.activated_at<s.instance_created_at or new.activated_at<p.created_at or new.due_at is distinct from s.activated_at+(p.definition->>'dueAfterMinutes')::integer*interval '1 minute'or new.approver_user_id is distinct from s.approver_user_id or new.approver_role is distinct from s.approver_role then raise exception 'Retain the actual canonical pending-stage clock.'using errcode='ADN02';end if;return new;end if;
 begin ctx=nullif(current_setting('workos.work_approval_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null or not exists(select 1 from users u join user_roles ur on ur.user_id=u.id join roles ro on ro.id=ur.role_id join user_organization_scopes sc on sc.user_id=u.id where u.id=(ctx->>'actorId')::uuid and u.status='Active'and ro.name=ctx->>'activeRole'and sc.organization_id=ctx->>'organizationId'and sc.legal_entity_id=ctx->>'legalEntityId'and sc.active)then raise exception 'Use the current scoped approval-notice command.'using errcode='ADN01';end if;
 if tg_table_name='approval_due_policies'then
  select * into p from approval_due_policies where organization_id=new.organization_id and legal_entity_id=new.legal_entity_id order by sequence desc limit 1;
  if new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.actor_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.sequence<>coalesce(p.sequence,0)+1 or new.effective_from<(clock_timestamp()at time zone'UTC')::date or(p.id is not null and new.effective_from<=p.effective_from)or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()then raise exception 'Append only prospective policy dates and actual adoption time.'using errcode='ADN02';end if;return new;
 elsif tg_table_name='approval_due_templates'then select * into p from approval_due_policies where id=new.policy_id;if p.organization_id is distinct from ctx->>'organizationId'or p.legal_entity_id is distinct from ctx->>'legalEntityId'or new.locale is distinct from p.definition->>'locale'or new.subject is distinct from p.definition->'template'->>'subject'or new.body is distinct from p.definition->'template'->>'body'then raise exception 'Use the retained scoped overdue template.'using errcode='ADN01';end if;return new;
 elsif tg_table_name='approval_due_runs'then
  select * into s from approval_due_source_events where origin=new.origin and instance_id=new.instance_id order by stage desc limit 1;
  if s.instance_id is null or new.organization_id is distinct from s.organization_id or new.legal_entity_id is distinct from s.legal_entity_id or new.organization_id is distinct from ctx->>'organizationId'or new.legal_entity_id is distinct from ctx->>'legalEntityId'or new.actor_id::text is distinct from ctx->>'actorId'or new.active_role is distinct from ctx->>'activeRole'or new.operation_id is distinct from ctx->>'operationId'or new.created_at<statement_timestamp()or new.created_at>clock_timestamp()or new.source_token<>encode(digest(new.source_canonical,'sha256'),'hex')or new.sequence<>(select coalesce(max(sequence),0)+1 from approval_due_runs where origin=new.origin and instance_id=new.instance_id)then raise exception 'Use exact scoped approval-clock evaluation.'using errcode='ADN03';end if;return new;
 elsif tg_table_name='approval_due_events'then select * into r from approval_due_runs where id=new.run_id;
 elsif tg_table_name='approval_due_recipients'then select x.* into r from approval_due_runs x join approval_due_events e on e.run_id=x.id where e.id=new.event_id;
 else select x.* into r from approval_due_runs x join approval_due_events e on e.run_id=x.id join approval_due_recipients n on n.event_id=e.id where n.id=new.recipient_id;
  if tg_table_name='approval_due_reads'then if ctx->>'actorId'is distinct from new.user_id::text or not exists(select 1 from approval_due_recipients where id=new.recipient_id and user_id=new.user_id)then raise exception 'Read only your exact owned recipient.'using errcode='ADN01';end if;end if;
 end if;
 if r.id is null or r.organization_id is distinct from ctx->>'organizationId'or r.legal_entity_id is distinct from ctx->>'legalEntityId'then raise exception 'Approval notice scope unavailable.'using errcode='ADN01';end if;return new;
end $$;
do $$declare t text;begin foreach t in array array['approval_due_policies','approval_due_templates','approval_due_bindings','approval_due_clocks','approval_due_runs','approval_due_events','approval_due_recipients','approval_due_deliveries','approval_due_reads']loop execute format('create trigger immutable_%I before update or delete on %I for each row execute function reject_commercial_draft_rewrite()',t,t);execute format('create trigger guarded_%I before insert on %I for each row execute function guard_approval_due_append()',t,t);end loop;end $$;
create function validate_approval_due_commit()returns trigger language plpgsql as $$declare e approval_due_events;c approval_due_clocks;p approval_due_policies;s approval_due_source_events;target uuid;ids uuid[];u uuid;n approval_due_recipients;reasons text[];checked timestamptz;begin
 if new.stage not between 0 and 9 or new.source_canonical::jsonb->>'origin' is distinct from new.origin or new.source_canonical::jsonb->>'instanceId' is distinct from new.instance_id::text or(new.source_canonical::jsonb->>'stage')::integer is distinct from new.stage or new.outcome->>'sourceToken' is distinct from new.source_token or new.outcome->>'state' is distinct from new.source_canonical::jsonb->>'state' or new.outcome->>'eventKey' is distinct from new.source_canonical::jsonb->>'eventKey' or new.outcome->>'state' not in('Unconfigured','Waiting','Overdue','Notified','Terminal','Stale')or new.outcome->>'disposition'not in('Emitted','Existing','NoEvent')then raise exception 'Exact retained evaluation outcome required.'using errcode='ADN03';end if;
 if new.outcome->>'disposition'='NoEvent'and(new.outcome->>'eventId'is not null or new.outcome->>'eventKey'is not null or new.outcome->>'state'in('Overdue','Notified'))then raise exception 'Suppressed evaluation cannot claim a notice.'using errcode='ADN03';end if;
 if new.outcome->>'disposition'='Existing'and not exists(select 1 from approval_due_events where id=new.outcome->>'eventId'and clock_id=new.clock_id)then raise exception 'Existing notice identity required.'using errcode='ADN03';end if;
 if new.outcome->>'disposition'<>'Emitted'then if exists(select 1 from approval_due_events where run_id=new.id)then raise exception 'Suppressed evaluation must not emit.'using errcode='ADN03';end if;return null;end if;
 select * into e from approval_due_events where run_id=new.id;select * into c from approval_due_clocks where id=new.clock_id;select pol.* into p from approval_due_policies pol join approval_due_bindings b on b.policy_id=pol.id where b.origin=new.origin and b.instance_id=new.instance_id;select * into s from approval_due_source_events where origin=c.origin and source_event_id=c.source_event_id;checked=(new.outcome->>'checkedAt')::timestamptz;
 if new.outcome->>'state'<>'Overdue'or new.outcome->>'eventKey'<>'approval.overdue_or_escalated'or new.outcome->>'eventId'is distinct from e.id or e.id is null or c.id is null or p.id is null or c.origin<>new.origin or c.instance_id<>new.instance_id or c.stage<>new.stage or s.organization_id<>new.organization_id or s.legal_entity_id<>new.legal_entity_id or not approval_due_current(c.origin,c.instance_id,c.stage)or checked>new.created_at or checked<=c.due_at or abs(extract(epoch from new.created_at-checked))>60 or e.clock_id<>c.id or e.operation_id<>new.operation_id or e.correlation_id<>new.correlation_id or not exists(select 1 from approval_due_templates where id=e.template_id and policy_id=p.id and locale=e.locale)then raise exception 'Emit only the exact retained current overdue stage.'using errcode='ADN03';end if;
 target=(p.definition->'target'->>'userId')::uuid;select array_agg(distinct id)into ids from unnest(array[c.approver_user_id,target])id;
 if(select count(*)from approval_due_recipients where event_id=e.id)<>cardinality(ids)then raise exception 'Complete mandatory recipient set required.'using errcode='ADN03';end if;
 foreach u in array ids loop
  if not exists(select 1 from users a join user_organization_scopes sc on sc.user_id=a.id join user_roles ur on ur.user_id=a.id join roles ro on ro.id=ur.role_id where a.id=u and a.status='Active'and sc.organization_id=new.organization_id and sc.legal_entity_id=new.legal_entity_id and sc.active and ro.name=case when u=c.approver_user_id then c.approver_role else p.definition->'target'->>'role'end)or(u=target and not exists(select 1 from user_roles ur join roles ro on ro.id=ur.role_id where ur.user_id=u and ro.name=p.definition->'target'->>'role'))then raise exception 'Current named mandatory role unavailable.'using errcode='ADN03';end if;
  reasons=array[]::text[];if u=target then reasons=array_append(reasons,'configured_escalation_target');end if;if u=c.approver_user_id then reasons=array_append(reasons,'current_stage_approver');end if;select * into n from approval_due_recipients where event_id=e.id and user_id=u;
  if n.id is null or n.reasons is distinct from reasons or not exists(select 1 from approval_due_deliveries where recipient_id=n.id and operation_id=new.operation_id and correlation_id=new.correlation_id)then raise exception 'Atomic in-app recipients/reasons/delivery required.'using errcode='ADN03';end if;
 end loop;return null;
end $$;
create constraint trigger approval_due_commit after insert on approval_due_runs deferrable initially deferred for each row execute function validate_approval_due_commit();
create index approval_due_clock_instance on approval_due_clocks(origin,instance_id,stage);
create index approval_due_recipient_inbox on approval_due_recipients(user_id,id);

-- A policy and its exact retained template are one append-only adoption.
create function validate_approval_due_policy_commit()returns trigger language plpgsql as $$begin
 if not exists(select 1 from approval_due_templates where policy_id=new.id and event_key='approval.overdue_or_escalated'and locale=new.definition->>'locale'and subject=new.definition->'template'->>'subject'and body=new.definition->'template'->>'body')then raise exception 'Complete retained due template required.'using errcode='ADN03';end if;return null;
end $$;
create constraint trigger approval_due_policy_commit after insert on approval_due_policies deferrable initially deferred for each row execute function validate_approval_due_policy_commit();
